#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Инициализация дисплея: адрес 0x27 (если не работает, попробуйте 0x3F), 16 столбцов, 2 строки
LiquidCrystal_I2C lcd(0x27, 16, 2);

// Пины подключения фоторезисторов
const int ldrPin1 = A0;
const int ldrPin2 = A1;

void setup() {
  // 1. Запуск монитора порта (скорость 9600 бод)
  Serial.begin(9600);

  // 2. Запуск дисплея и включение подсветки
  lcd.init();
  lcd.backlight();

  // Приветствие в Serial
  Serial.println("System started. Reading sensors...");
}

void loop() {
  // Считываем сырые значения с АЦП (от 0 до 1023)
  int raw1 = analogRead(ldrPin1);
  int raw2 = analogRead(ldrPin2);

  // Переводим значения в проценты (от 0 до 100%)
  int pct1 = map(raw1, 0, 1023, 0, 100);
  int pct2 = map(raw2, 0, 1023, 0, 100);

  // --- ВЫВОД НА ДИСПЛЕЙ 1602 ---
  lcd.setCursor(0, 0);
  lcd.print("S1:");
  lcd.print(raw1);
  lcd.print(" (");
  lcd.print(pct1);
  lcd.print("%)   "); // Пробелы стирают старые символы

  lcd.setCursor(0, 1);
  lcd.print("S2:");
  lcd.print(raw2);
  lcd.print(" (");
  lcd.print(pct2);
  lcd.print("%)   ");


  // --- ВЫВОД В МОНИТОР ПОРТА (Serial Monitor) ---
  Serial.print("Sensor 1 -> Raw: ");
  Serial.print(raw1);
  Serial.print("\t | Percent: ");
  Serial.print(pct1);
  Serial.print("%\t|\t");

  Serial.print("Sensor 2 -> Raw: ");
  Serial.print(raw2);
  Serial.print("\t | Percent: ");
  Serial.print(pct2);
  Serial.println("%");

  // Задержка 250 мс для стабильности отображения
  delay(250);
}
